/* Q14: instructions fetched per cycle.
 * Times every NOP block (generated by gen_nops.py, run via q14_kt.c).
 * Output CSV: nop_len,count,footprint_bytes,trial,ticks,cycles,instrs,ipc,bytes_per_cycle */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#include "kbackend.h"

int main(int argc, char **argv)
{
    int trials = 11;
    double target = 2e7;   /* instructions per measurement */
    int opt;
    while ((opt = getopt(argc, argv, "t:n:")) != -1) {
        switch (opt) {
        case 't': trials = atoi(optarg); break;
        case 'n': target = atof(optarg); break;
        default:
            fprintf(stderr, "usage: %s [-t trials] [-n instrs per measurement]\n", argv[0]);
            return 1;
        }
    }

    kb_init();
    calib_t c = bench_calibrate("fetch", kb_calib_timer);

    uint64_t ne = kb_count();
    uint64_t *len = malloc(ne * sizeof(*len)), *count = malloc(ne * sizeof(*count));
    char name[32];
    for (uint64_t e = 0; e < ne; e++)
        kb_entry(e, name, sizeof(name), &len[e], &count[e]);

    printf("nop_len,count,footprint_bytes,trial,ticks,cycles,instrs,ipc,bytes_per_cycle\n");
    for (int t = 0; t < trials; t++) {
        for (uint64_t e = 0; e < ne; e++) {
            uint64_t iters = (uint64_t)(target / count[e]) + 1;
            kb_run(e, iters / 10 + 1);   /* warm i-cache / uop cache */
            uint64_t ticks = kb_run(e, iters);
            double cyc = ticks * c.cyc_per_tick;
            double n = (double)iters * (count[e] + 1);   /* + fused dec/jnz */
            double bytes = (double)iters * count[e] * len[e];
            printf("%llu,%llu,%llu,%d,%llu,%.0f,%.0f,%.4f,%.4f\n",
                   (unsigned long long)len[e], (unsigned long long)count[e],
                   (unsigned long long)(len[e] * count[e]), t,
                   (unsigned long long)ticks, cyc, n, n / cyc, bytes / cyc);
        }
        fflush(stdout);
    }
    bench_recheck(&c, kb_calib_timer);
    kb_fini();
    return 0;
}
